/**
 * The generated file of queries: each query of a file, described, written
 * out as a function of its own, with the interfaces of its rows and of its
 * parameters.
 *
 * It is laid out as the file of types is, as Prettier and Biome lay out
 * code by default, so that such a formatter leaves it as it is. The types
 * of the database come from the file of types, as a namespace, so that no
 * name of the one is taken for a name of the other.
 *
 * @module
 */

import { relative, sep } from "node:path";
import type { TsType } from "./catalog.ts";
import type { DescribedParameter, DescribedQuery } from "./describe.ts";
import { doc, keyOf, stringLiteral, tooWide } from "./render.ts";

/** Where the file goes, and the file of types it imports. */
export interface RenderQueriesOptions {
  /**
   * The directory the file goes in: the paths it holds, of the query files
   * and of the file of types, are relative to it.
   */
  readonly base: string;

  /** The path of the file of types. */
  readonly types: string;
}

/** Writes the file of the queries of `queries`. */
export function renderQueries(
  queries: readonly DescribedQuery[],
  options: RenderQueriesOptions,
): string {
  const rows = queries.some((query) => query.fields !== null);
  const counts = queries.some((query) => query.fields === null);
  const imported = [
    ...(rows || counts
      ? [
          `import { ${[...(counts ? ["queryCount"] : []), ...(rows ? ["queryRows"] : [])].join(", ")} } from "@tetsujs/sql";`,
          'import type { Kysely } from "kysely";',
          `import type * as Database from ${stringLiteral(importOf(options.base, options.types))};`,
        ]
      : ["export {};"]),
  ];
  const parts = [
    HEADER,
    imported.join("\n"),
    ...queries.flatMap((query) =>
      declarations(query, relativeTo(options.base, query.file.path)),
    ),
  ];

  return `${parts.join("\n\n")}\n`;
}

/** The comment at the top: what the file is. */
const HEADER = `/**
 * The functions of the query files, typed by the database the migrations
 * build, as Postgres describes each query.
 *
 * Generated by \`tetsu-sql types:generate\`: change the queries, not this
 * file, and generate it again.
 *
 * @module
 */`;

/**
 * The declarations of a query, its file at `path`: its interfaces, its
 * text, its function.
 */
function declarations(query: DescribedQuery, path: string): string[] {
  const { file, fields, parameters } = query;
  const pascal = `${file.name.slice(0, 1).toUpperCase()}${file.name.slice(1)}`;
  const constant = file.name
    .replace(/[A-Z]/g, (letter) => `_${letter}`)
    .toUpperCase();

  return [
    ...(fields === null
      ? []
      : [
          [
            `/** A row of {@link ${file.name}}. */`,
            `export interface ${pascal}Row {`,
            ...fields.map((field) =>
              member(field.name, field.values.reads, field.nullable),
            ),
            "}",
          ].join("\n"),
        ]),
    ...(parameters.length === 0
      ? []
      : [
          [
            `/** The parameters of {@link ${file.name}}. */`,
            `export interface ${pascal}Params {`,
            ...parameters.map((parameter) =>
              member(
                parameter.name,
                parameter.values.writes,
                parameter.nullable,
              ),
            ),
            "}",
          ].join("\n"),
        ]),
    statement(constant, file.text, parameters),
    [
      ...doc(
        `${file.doc === undefined ? "" : `${file.doc}\n\n`}\`${path}\``,
        "",
      ),
      ...signature(
        file.name,
        [
          "db: Kysely<Database.DB>",
          ...(parameters.length === 0 ? [] : [`params: ${pascal}Params`]),
        ],
        fields === null ? "Promise<bigint>" : `Promise<${pascal}Row[]>`,
      ),
      call(fields === null ? "queryCount" : "queryRows", [
        "db",
        constant,
        ...(parameters.length === 0 ? [] : ["params"]),
      ]),
      "}",
    ].join("\n"),
  ];
}

/**
 * The constant of a query's statement: its text, as a template, and its
 * parameters. Its name too long for its line, the object goes on the
 * lines after it, as a formatter breaks an assignment.
 */
function statement(
  constant: string,
  text: string,
  parameters: readonly DescribedParameter[],
): string {
  const head = `const ${constant} = {`;
  const [open, indent, close] = tooWide(head)
    ? [`const ${constant} =\n  {`, "    ", "  };"]
    : [head, "  ", "};"];

  return [
    open,
    `${indent}text: \`${template(text)}\`,`,
    list(
      `${indent}names: `,
      indent,
      parameters.map((parameter) => stringLiteral(parameter.name)),
      ["[", "]"],
      "",
    ),
    list(
      `${indent}arrays: `,
      indent,
      parameters.flatMap((parameter) =>
        parameter.literal === undefined
          ? []
          : [`${keyOf(parameter.name)}: ${stringLiteral(parameter.literal)}`],
      ),
      ["{", "}"],
      " ",
    ),
    close,
  ].join("\n");
}

/**
 * Text as the inside of a template literal that reads as it: a backslash,
 * a backtick and `${` escaped, and a carriage return too, as JavaScript
 * reads one in a template as a line break.
 */
function template(text: string): string {
  return text
    .replaceAll("\\", "\\\\")
    .replaceAll("`", "\\`")
    .replaceAll("${", "\\${")
    .replaceAll("\r", "\\r");
}

/**
 * A member of an interface, its type and NULL when it may be NULL. Too
 * long, its type is broken as Biome breaks it: a union a member a line,
 * unless it is one name and NULL, which stays as it is; an array of such
 * a union, inside its brackets.
 */
function member(name: string, type: TsType, nullable: boolean): string {
  const whole =
    nullable && !(type.kind === "keyword" && type.name === "unknown")
      ? union([type, NULL])
      : type;
  const key = keyOf(name);
  const line = `  ${key}: ${textOf(whole)};`;

  if (!tooWide(line)) {
    return line;
  }

  if (whole.kind === "union" && !hugs(whole)) {
    return `  ${key}:\n${broken(whole, "    ")};`;
  }

  if (
    whole.kind === "array" &&
    whole.element.kind === "union" &&
    !hugs(whole.element)
  ) {
    return `  ${key}: ${whole.readonly ? "readonly " : ""}(\n${broken(whole.element, "    ")}\n  )[];`;
  }

  return line;
}

/** NULL, as a member of a union. */
const NULL: TsType = { kind: "keyword", name: "null" };

/** The words of TypeScript's own types, which a name of a type is not. */
const KEYWORDS: ReadonlySet<string> = new Set([
  "string",
  "number",
  "bigint",
  "boolean",
  "unknown",
  "object",
  "null",
]);

/** A union of `types`, its own unions taken apart. */
function union(types: readonly TsType[]): TsType {
  return { kind: "union", members: types.flatMap(membersOf) };
}

/** The members of a type, as a union: itself, unless it is one. */
function membersOf(type: TsType): TsType[] {
  return type.kind === "union" ? type.members.flatMap(membersOf) : [type];
}

/**
 * Whether a union stays on its line however long: one name of a type, such
 * as `Date` or an alias, and NULL.
 */
function hugs(type: TsType & { kind: "union" }): boolean {
  const others = membersOf(type).filter(
    (member) => !(member.kind === "keyword" && member.name === "null"),
  );
  const [only] = others;

  return (
    others.length === 1 &&
    only !== undefined &&
    (only.kind === "alias" ||
      (only.kind === "keyword" && !KEYWORDS.has(only.name)))
  );
}

/** A union, a member a line. */
function broken(type: TsType & { kind: "union" }, indent: string): string {
  return membersOf(type)
    .map((member) => `${indent}| ${textOf(member)}`)
    .join("\n");
}

/** A type, written: an alias of the file of types by its namespace. */
function textOf(type: TsType): string {
  switch (type.kind) {
    case "keyword":
      return type.name;
    case "alias":
      return `Database.${type.name}`;
    case "union":
      return membersOf(type).map(textOf).join(" | ");
    case "array": {
      const element = textOf(type.element);

      return `${type.readonly ? "readonly " : ""}${type.element.kind === "union" ? `(${element})` : element}[]`;
    }
  }
}

/**
 * A list of items after `head`, between brackets: on one line when it
 * fits, otherwise one item a line, with a comma after each, inside the
 * object at `indent`.
 */
function list(
  head: string,
  indent: string,
  items: readonly string[],
  [open, close]: readonly [string, string],
  padding: string,
): string {
  const flat =
    items.length === 0
      ? `${head}${open}${close},`
      : `${head}${open}${padding}${items.join(", ")}${padding}${close},`;

  if (!tooWide(flat)) {
    return flat;
  }

  return [
    `${head}${open}`,
    ...items.map((item) => `${indent}  ${item},`),
    `${indent}${close},`,
  ].join("\n");
}

/** A function's first line, or its parameters a line each when it is too long. */
function signature(
  name: string,
  parameters: readonly string[],
  returns: string,
): string[] {
  const flat = `export function ${name}(${parameters.join(", ")}): ${returns} {`;

  if (!tooWide(flat)) {
    return [flat];
  }

  return [
    `export function ${name}(`,
    ...parameters.map((parameter) => `  ${parameter},`),
    `): ${returns} {`,
  ];
}

/** The function's body: a call, its arguments a line each when it is too long. */
function call(callee: string, args: readonly string[]): string {
  const flat = `  return ${callee}(${args.join(", ")});`;

  if (!tooWide(flat)) {
    return flat;
  }

  return [
    `  return ${callee}(`,
    ...args.map((arg) => `    ${arg},`),
    "  );",
  ].join("\n");
}

/** A path, relative to `base`, with slashes. */
function relativeTo(base: string, path: string): string {
  return relative(base, path).split(sep).join("/");
}

/** How a file in `base` imports the file at `path`. */
function importOf(base: string, path: string): string {
  const relativePath = relativeTo(base, path);

  return relativePath.startsWith(".") ? relativePath : `./${relativePath}`;
}
